-- Access QueryDef: 24-0710_Справка_22_11_Осв_Филиалы_Слайды
-- Type: 0

SELECT p.dateRslt, IIf(IsNull(p![ogNm]),"итого",p![ogNm]) AS ogNm, p.branch, p.branchName, IIf(IsNull(p![cstAgPnCode]),"всего",p![cstAgPnCode]) AS cstAgPnCode, c.cstapCstName, IIf(IsNull(p![ag_lim]),0,p![ag_lim])+IIf(IsNull(p![iv_lim]),0,p![iv_lim])+IIf(IsNull(p![uk_lim]),0,p![uk_lim]) AS lim, p.ag_lim, IIf(p![ag_PlFulfillment]+p![ag_PlOverFulfillment]=0,Null,p![ag_PlFulfillment]+p![ag_PlOverFulfillment]) AS ag_Ful_OverFul, (p![ag_PlFulfillment]+p![ag_PlOverFulfillment])/p![ag_lim] AS ag_LimPc, IIf([ag_PlOverLimit]=0,Null,[ag_PlOverLimit]) AS ag_PlOverLimit_, p.iv_lim, p.uk_lim, IIf(p![ag_PlAccum]=0,Null,p![ag_PlAccum]) AS ag_PlAccum, IIf(p![ag_PlFulfillment]=0,Null,p![ag_PlFulfillment]) AS ag_PlFulfillment, IIf(IsNull(p![ag_PlAccum]) Or p![ag_PlAccum]=0,Null,p![ag_PlFulfillment]/p![ag_PlAccum]) AS ag_PlPz, IIf(p![ag_PlOverFulfillment]=0,Null,p![ag_PlOverFulfillment]) AS ag_PlOverFulfillment, p.ag_PlPercent, p.ag_Pl AS ag_Pl_M, p.ag_acceptedTtl AS ag_acceptedTtl_M, (IIf(IsNull(p!ag_presentedAccum),0,p!ag_presentedAccum)+IIf(IsNull(p!ag_presentedRalpAccum),0,p!ag_presentedRalpAccum))-(IIf(IsNull(p!ag_acceptedAccum),0,p!ag_acceptedAccum)+IIf(IsNull(p!ag_acceptedRalpAccum),0,p!ag_acceptedRalpAccum)) AS ag_acceptedNot, IIf(IsNull([ag_Pl_M]) Or [ag_Pl_M]=0,Null,[ag_acceptedTtl_M]/[ag_Pl_M]) AS ag_PlPz_M, MonthName(Month([dateRslt])) AS mn, p.ogNm AS ogNmSort, p.cstAgPnCode AS cstAgPnCodeSort, p.np_acceptedTtlAccum, p.cstapKey
FROM ipgChRsltPlCstPercent AS p LEFT JOIN ags_cstAgPn AS c ON p.cstAgPnCode = c.cstapIpgPnN;
